import 'package:test/test.dart';

import '../tool/import_nullable_references.dart';

const _mapped = '''
// Generated by swagger_parser. Do not edit.

import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:soundspan_api/src/nullable_references.dart' as mapped1;

part 'item.freezed.dart';

class Item {
  final mapped1.NullableLibraryTrack? track;
}
''';

void main() {
  test('a model that uses a nullable alias also imports the codec library '
      'without a prefix', () {
    final source = withNullableReferencesImport(_mapped)!;

    expect(
      source,
      contains(
        "import 'package:soundspan_api/src/nullable_references.dart';\n"
        "import 'package:soundspan_api/src/nullable_references.dart' "
        'as mapped1;',
      ),
    );
  });

  test('a model that already has the import is unchanged', () {
    final once = withNullableReferencesImport(_mapped)!;

    expect(withNullableReferencesImport(once), isNull);
  });

  test('a model without a nullable alias is unchanged', () {
    expect(
      withNullableReferencesImport(
        "import 'package:freezed_annotation/freezed_annotation.dart';\n",
      ),
      isNull,
    );
  });
}
